```java
import java.io.FileWriter;
import java.io.PrintWriter;
import java.io.BufferedReader;
import java.io.FileReader;

public class Diary {
    public static void main(String[] args) {
        String fileName = "score.txt";
        String[] names = {"kim", "lee", "park"};
        int[] scores = {90, 85, 70};

        // 1) 파일에 쓰기 (false: 덮어쓰기)
        FileWriter fw = null;
        try {
            fw = new FileWriter(fileName, false);
            PrintWriter out = new PrintWriter(fw);
            int sum = 0;
            for (int i = 0; i < names.length; i++) {
                out.printf("%s %d\n", names[i], scores[i]);
                sum += scores[i];
            }
            out.printf("평균 %.1f\n", sum / (double) names.length);
            out.close();
        } catch (Exception e) {
            System.out.println("실패:" + e);
        } finally {
            try {
                if (fw != null) { fw.close(); }
            } catch (Exception e) {}
        }

        // 2) 파일 읽어서 화면에 출력
        FileReader fr = null;
        BufferedReader br = null;
        try {
            fr = new FileReader(fileName);
            br = new BufferedReader(fr);
            while (true) {
                String line = br.readLine();
                if (line == null) {
                    break;
                }
                System.out.println(line);
            }
        } catch (Exception e) {
            System.out.println("실패:" + e);
        } finally {
            try {
                if (br != null) { br.close(); }
            } catch (Exception e) {}
            try {
                if (fr != null) { fr.close(); }
            } catch (Exception e) {}
        }
    }
}
```

- 평균은 245 / 3 = 81.666... 이고 `%.1f` 로 소수점 한 자리까지 반올림해 `81.7` 이 돼요.
- `sum / (double) names.length` 처럼 한쪽을 실수로 바꿔야 정수 나눗셈(81)이 되지 않아요.
- 결과 파일이라 강사 팁대로 `false` 로 열었어요. 몇 번을 실행해도 내용이 쌓이지 않아요.
